    byte[] data = schema.encode(buffer, message);
    int size = data.length;
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(data);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    if (size > 536870911) { // 1 << 29
        throw new OutOfMemoryError("Message is too large: " + size);
    }
    // Write the size as a 32-bit unsigned integer
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(data, 0, size);
    return size;
}

