public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message using the provided schema
    byte[] serialised = schema.toByteArray(message, buffer);
    // Get the length of the serialized message
    int size = serialised.length;
    // Write the length of the message as a variable-length integer
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    codedOut.writeRawVarint32(size);
    // Write the serialized message data
    codedOut.writeRawBytes(serialised);
    // Clear the buffer to free up memory
    buffer.clear();
    // Return the size of the message
    return size;
}

