public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000);
    int month = (int) (timeBucket % 10000 / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the compressed day based on the dayStep
    int compressedDay = day - (day - 1) % dayStep;

    // Reconstruct the time bucket with the compressed day
    return (long) year * 10000 + month * 100 + compressedDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 100000000);
    int month = (int) (timeBucket / 1000000 % 100);
    int day = (int) (timeBucket / 10000 % 100);

    if (dayStep == 11) {
        if (day <= 3) {
            day = 1;
        } else if (day <= 13) {
            day = 12;
        } else if (day <= 23) {
            day = 22;
        } else {
            day = 23;
        }
    } else if (dayStep == 14) {
        if (day <= 7) {
            day = 1;
        } else if (day <= 21) {
            day = 15;
        } else {
            day = 28;
        }
    } else if (dayStep == 30) {
        if (day <= 10) {
            day = 1;
        } else if (day <= 20) {
            day = 10;
        } else {
            day = 28;
        }
    } else if (dayStep == 31) {
        if (day == 31) {
            day = 31;
        } else {
            day = 1 + ((day - 1) / 30) * 30 + 1;
        }
    } else if (dayStep == 365) {
        if (day == 365) {
            day = 365;
        } else {
            day = 1 + ((day - 1) / 365) * 365;
        }
    }

    return year * 100000000 + month * 1000000 + day * 10000;
}

