private static String performVariableSubstitution(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int index = 0;
    while (index < value.length()) {
        int start = value.indexOf("${", index);
        if (start == -1) {
            result.append(value.substring(index));
            break;
        }
        result.append(value.substring(index, start));
        int end = value.indexOf("}", start + 2);
        if (end == -1) {
            result.append(value.substring(start));
            break;
        }
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        } else {
            result.append("${").append(varName).append("}");
        }
        index = end + 1;
    }
    return result.toString();
}

