    for (int shift = 0; shift < 64; shift += 7) {
        int b = input.read();
        if (b == -1) {
            throw new EOFException();
        }
        result |= ((b & 0x7F) << shift);
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    throw new IOException("malformed Varint");
}

