protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Create a list to store the vertices in the tour order
    List<V> pathVertices = new ArrayList<>();

    // Start with an arbitrary vertex from the tour
    V startVertex = tour.iterator().next();
    pathVertices.add(startVertex);

    // Add the vertices in the order of the edges in the tour
    Iterator<E> tourIterator = tour.iterator();
    while (tourIterator.hasNext()) {
        E edge = tourIterator.next();
        Set<E> incidentEdges = graph.incidentEdges(startVertex);
        for (E incidentEdge : incidentEdges) {
            if (incidentEdge.equals(edge)) {
                V nextVertex = edge.equals(graph.getEdgeSource(edge)) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
                pathVertices.add(nextVertex);
                startVertex = nextVertex;
                break;
            }
        }
    }

    // Create and return the graph path
    return graph.getPath(pathVertices);
}

